CREATE TABLE asset_types (asset_type_id TEXT, name TEXT, category TEXT, deposit_amount TEXT, return_days TEXT);
CREATE TABLE owners (owner_id TEXT, name TEXT, owner_type TEXT);
CREATE TABLE locations (location_id TEXT, name TEXT, location_type TEXT);
CREATE TABLE reusable_assets (asset_id TEXT, asset_type_id TEXT, owner_id TEXT, serial_number TEXT, status TEXT, current_location_id TEXT, acquired_date TEXT);
CREATE TABLE shipments (shipment_id TEXT, from_location_id TEXT, to_location_id TEXT, owner_id TEXT, status TEXT, dispatch_date TEXT, expected_return_date TEXT);
CREATE TABLE custody_events (custody_event_id TEXT, asset_id TEXT, shipment_id TEXT, event_type TEXT, event_date TEXT, from_location_id TEXT, to_location_id TEXT, actor_id TEXT, issue_type TEXT);
CREATE TABLE return_authorizations (return_authorization_id TEXT, asset_id TEXT, shipment_id TEXT, status TEXT, requested_date TEXT, received_date TEXT);
CREATE TABLE inspections (inspection_id TEXT, asset_id TEXT, return_authorization_id TEXT, inspection_date TEXT, result TEXT, notes TEXT);
CREATE TABLE repairs (repair_id TEXT, asset_id TEXT, inspection_id TEXT, opened_date TEXT, closed_date TEXT, status TEXT, cost TEXT);
CREATE TABLE deposit_ledger (ledger_id TEXT, asset_id TEXT, return_authorization_id TEXT, entry_type TEXT, amount TEXT, entry_date TEXT);
